messages.content:
Tool response:
Tool: bulk_reschedule_sessions
Description: Bulk Reschedule Sessions
Parameters:
    {
      "type": "object",
      "properties": {
        "subject_name": {
          "type": "string",
          "description": "Subject name to filter sessions",
          "title": "Subject Name"
        },
        "start_date": {
          "type": "string",
          "description": "Start date of the target week (YYYY-MM-DD format)",
          "title": "Start Date"
        },
        "end_date": {
          "type": "string",
          "description": "End date of the target week (YYYY-MM-DD format)",
          "title": "End Date"
        }
      },
      "required": [
        "subject_name",
        "start_date",
        "end_date"
      ]
    }

Tool response:
Tool: execute_bulk_reschedule
Description: Execute Bulk Reschedule
Parameters:
    {
      "type": "object",
      "properties": {
        "session_updates": {
          "items": {
            "properties": {
              "session_id": {
                "type": "integer",
                "title": "Session Id"
              },
              "new_start_time": {
                "type": "string",
                "title": "New Start Time"
              },
              "new_end_time": {
                "type": "string",
                "title": "New End Time"
              }
            },
            "type": "object",
            "required": [
              "session_id",
              "new_start_time",
              "new_end_time"
            ],
            "title": "SessionUpdate"
          },
          "type": "array",
          "title": "Session Updates"
        }
      },
      "required": [
        "session_updates"
      ]
    }
